public class OrderPayloadParser {
    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public class PayloadException extends Exception {}

    public static OrderPayloadParser.Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('The request body must not be blank.');
        }

        try {
            Object decoded = JSON.deserializeUntyped(body);
            if (!(decoded instanceof Map<String, Object>)) {
                throw new PayloadException('The JSON payload must be an object.');
            }

            Map<String, Object> payload = (Map<String, Object>) decoded;
            Order parsedOrder = new Order();

            Object numberValue = payload.get('number');
            if (!(numberValue instanceof String) || String.isBlank((String) numberValue)) {
                throw new PayloadException('The order number is required.');
            }
            parsedOrder.orderNumber = (String) numberValue;

            Object dateValue = payload.get('date');
            if (dateValue != null) {
                if (!(dateValue instanceof String)) {
                    throw new PayloadException('The order date must be an ISO date string.');
                }

                String dateText = (String) dateValue;
                if (!isIsoDate(dateText)) {
                    throw new PayloadException('The order date must use yyyy-MM-dd format.');
                }
                parsedOrder.orderDate = Date.valueOf(dateText);
            }

            parsedOrder.currencyCode = optionalString(payload.get('currency'), 'currency');

            Object customerValue = payload.get('customer');
            if (customerValue != null) {
                if (!(customerValue instanceof Map<String, Object>)) {
                    throw new PayloadException('Customer must be an object.');
                }
                Map<String, Object> customer = (Map<String, Object>) customerValue;
                parsedOrder.customerEmail = optionalString(customer.get('email'), 'customer.email');
            }

            parsedOrder.lines = new List<Line>();
            parsedOrder.total = 0;

            Object linesValue = payload.get('lines');
            if (linesValue != null) {
                if (!(linesValue instanceof List<Object>)) {
                    throw new PayloadException('Lines must be an array.');
                }

                for (Object lineValue : (List<Object>) linesValue) {
                    if (!(lineValue instanceof Map<String, Object>)) {
                        throw new PayloadException('Each line must be an object.');
                    }

                    Map<String, Object> linePayload = (Map<String, Object>) lineValue;
                    Object skuValue = linePayload.get('sku');
                    if (!(skuValue instanceof String) || String.isBlank((String) skuValue)) {
                        throw new PayloadException('Each line requires a SKU.');
                    }

                    Object quantityValue = linePayload.get('quantity');
                    if (quantityValue == null) {
                        throw new PayloadException('Each line requires a positive integer quantity.');
                    }
                    Decimal quantityDecimal = numericValue(quantityValue, 'quantity');
                    if (quantityDecimal <= 0 ||
                        quantityDecimal != quantityDecimal.setScale(0, RoundingMode.DOWN)) {
                        throw new PayloadException('Each line requires a positive integer quantity.');
                    }

                    Object unitPriceValue = linePayload.get('unitPrice');
                    if (unitPriceValue == null) {
                        throw new PayloadException('Each line requires a non-negative unit price.');
                    }
                    Decimal unitPrice = numericValue(unitPriceValue, 'unitPrice');
                    if (unitPrice < 0) {
                        throw new PayloadException('Each line requires a non-negative unit price.');
                    }

                    Decimal discount = 0;
                    if (linePayload.containsKey('discount') && linePayload.get('discount') != null) {
                        discount = numericValue(linePayload.get('discount'), 'discount');
                    }
                    if (discount < 0 || discount > 1) {
                        throw new PayloadException('Discount must be between 0 and 1.');
                    }

                    Line parsedLine = new Line();
                    parsedLine.sku = (String) skuValue;
                    parsedLine.quantity = quantityDecimal.intValue();
                    parsedLine.unitPrice = unitPrice;
                    parsedLine.discount = discount;
                    parsedLine.lineTotal =
                        Decimal.valueOf(String.valueOf(parsedLine.quantity)) *
                        unitPrice *
                        (Decimal.valueOf('1') - discount);
                    parsedLine.lineTotal = parsedLine.lineTotal.setScale(2, RoundingMode.HALF_UP);

                    parsedOrder.lines.add(parsedLine);
                    parsedOrder.total += parsedLine.lineTotal;
                }
            }

            return parsedOrder;
        } catch (PayloadException ex) {
            throw ex;
        } catch (Exception ex) {
            throw new PayloadException('The order payload is invalid.');
        }
    }

    public static String toAcknowledgement(OrderPayloadParser.Order order) {
        Map<String, Object> acknowledgement = new Map<String, Object>();
        acknowledgement.put('number', order == null ? null : order.orderNumber);
        acknowledgement.put('status', 'RECEIVED');
        acknowledgement.put(
            'lineCount',
            order == null || order.lines == null ? 0 : order.lines.size()
        );
        acknowledgement.put('total', order == null || order.total == null ? 0 : order.total);
        return JSON.serialize(acknowledgement);
    }

    private static Boolean isIsoDate(String value) {
        if (value == null || value.length() != 10 ||
            value.substring(4, 5) != '-' ||
            value.substring(7, 8) != '-') {
            return false;
        }

        String digits = '0123456789';
        for (Integer i = 0; i < value.length(); i++) {
            if (i == 4 || i == 7) {
                continue;
            }
            if (!digits.contains(value.substring(i, i + 1))) {
                return false;
            }
        }
        return true;
    }

    private static String optionalString(Object value, String fieldName) {
        if (value == null) {
            return null;
        }
        if (!(value instanceof String)) {
            throw new PayloadException(fieldName + ' must be a string.');
        }
        return (String) value;
    }

    private static Decimal numericValue(Object value, String fieldName) {
        if (!(value instanceof Integer) &&
            !(value instanceof Long) &&
            !(value instanceof Decimal) &&
            !(value instanceof Double)) {
            throw new PayloadException(fieldName + ' must be a number.');
        }
        return Decimal.valueOf(String.valueOf(value));
    }
}
