public with sharing class LogPurgeJob implements Schedulable {
    public LogPurgeJob() {
    }

    public void execute(SchedulableContext context) {
        Database.executeBatch(new PurgeBatch(), 200);
    }

    public static Id scheduleNightly() {
        return System.schedule(
            'Log purge (nightly)',
            '0 0 2 * * ?',
            new LogPurgeJob()
        );
    }

    private class PurgeBatch implements Database.Batchable<SObject> {
        public Database.QueryLocator start(Database.BatchableContext context) {
            Datetime regularCutoff = Datetime.now().addDays(-30);
            Datetime errorCutoff = Datetime.now().addDays(-180);

            return Database.getQueryLocator([
                SELECT Id
                FROM FB_Integration_Log__c
                WHERE (CreatedDate < :errorCutoff AND Level__c = 'ERROR')
                   OR (
                       CreatedDate < :regularCutoff
                       AND (Level__c != 'ERROR' OR Level__c = null)
                   )
            ]);
        }

        public void execute(Database.BatchableContext context, List<SObject> scope) {
            if (!scope.isEmpty()) {
                delete scope;
            }
        }

        public void finish(Database.BatchableContext context) {
        }
    }
}
