    public override void onValidate(Map<Id, SObject> existingRecords) {
        validateNonNegativeAmounts();

        for (Opportunity opportunity : (List<Opportunity>) Records) {
            Opportunity existingOpportunity =
                (Opportunity) existingRecords.get(opportunity.Id);

            if (
                existingOpportunity != null &&
                existingOpportunity.StageName == 'Closed Won' &&
                existingOpportunity.Amount != opportunity.Amount
            ) {
                error(
                    'Amount cannot change on a won opportunity.',
                    opportunity,
                    Schema.SObjectType.Opportunity.fields.Amount
                );
            }
        }
