            if (fieldSet.getName().equalsIgnoreCase('Credit_Review')) {
                Map<String, Schema.SObjectField> accountFields =
                    Account.SObjectType.getDescribe().fields.getMap();

                for (Schema.FieldSetMember member : fieldSet.getFields()) {
                    Schema.SObjectField field =
                        accountFields.get(member.getFieldPath());

                    if (field != null && !fields.contains(field)) {
                        fields.add(field);
                    }
                }
                break;
            }
        }

        return fields;
