public class ErpCustomerSync implements Database.Batchable<Account>, Database.AllowsCallouts {
    private Set<Id> accountIds;

    private class CustomerPayload {
        public String salesforceId;
        public String name;
        public String country;
    }

    public ErpCustomerSync(List<Account> accounts) {
        accountIds = new Set<Id>();

        for (Account account : accounts) {
            accountIds.add(account.Id);
        }
    }

    public Database.QueryLocator start(Database.BatchableContext context) {
        return Database.getQueryLocator([
            SELECT Id, Name, BillingCountry
            FROM Account
            WHERE Id IN :accountIds
        ]);
    }

    public void execute(Database.BatchableContext context, List<Account> scope) {
        for (Account account : scope) {
            CustomerPayload customer = new CustomerPayload();
            customer.salesforceId = String.valueOf(account.Id);
            customer.name = account.Name;
            customer.country = String.isBlank(account.BillingCountry)
                ? null
                : account.BillingCountry;

            HttpRequest request = new HttpRequest();
            request.setEndpoint('callout:ERP/api/customers');
            request.setMethod('POST');
            request.setHeader('Content-Type', 'application/json');
            request.setBody(JSON.serialize(
                new List<CustomerPayload>{ customer }
            ));

            // One request per account, as required by the ERP traceability
            // requirement. Error handling and retries are out of scope.
            new Http().send(request);
        }
    }

    public void finish(Database.BatchableContext context) {
    }
}
