trigger CaseTrigger on Case (after update) {
    List<Id> newlyClosedCaseIds = new List<Id>();

    for (Case currentCase : Trigger.new) {
        Case oldCase = Trigger.oldMap.get(currentCase.Id);

        if (!oldCase.IsClosed && currentCase.IsClosed && currentCase.ContactId != null) {
            newlyClosedCaseIds.add(currentCase.Id);
        }
    }

    if (!newlyClosedCaseIds.isEmpty()) {
        // A transaction can enqueue at most 50 Queueable jobs. Enqueue one
        // bulk job instead of one job per case so bulk closures are supported.
        System.enqueueJob(new CaseSurveyJob(newlyClosedCaseIds));
    }
}
