public without sharing class CaseSurveyJob implements Queueable {
    private List<Id> caseIds;

    public CaseSurveyJob(Id caseId) {
        this(new List<Id>{ caseId });
    }

    public CaseSurveyJob(List<Id> caseIds) {
        this.caseIds = caseIds == null ? new List<Id>() : new List<Id>(caseIds);
    }

    public void execute(QueueableContext context) {
        if (caseIds.isEmpty()) {
            return;
        }

        List<Case> cases = [
            SELECT Id, CaseNumber, ContactId
            FROM Case
            WHERE Id IN :caseIds
        ];

        List<Task> surveyTasks = new List<Task>();
        List<Id> taskCaseIds = new List<Id>();

        for (Case currentCase : cases) {
            if (currentCase.ContactId == null) {
                continue;
            }

            surveyTasks.add(new Task(
                WhatId = currentCase.Id,
                WhoId = currentCase.ContactId,
                Subject = 'CSAT survey: ' + currentCase.CaseNumber,
                ActivityDate = Date.today().addDays(2),
                Status = 'Not Started'
            ));
            taskCaseIds.add(currentCase.Id);
        }

        if (surveyTasks.isEmpty()) {
            return;
        }

        // Partial-success DML prevents an invalid task from blocking tasks
        // for other cases in the same bulk job.
        Database.SaveResult[] results = Database.insert(surveyTasks, false);

        for (Integer i = 0; i < results.size(); i++) {
            if (!results[i].isSuccess()) {
                for (Database.Error error : results[i].getErrors()) {
                    System.debug(
                        LoggingLevel.ERROR,
                        'Failed to create CSAT survey task for Case ' +
                        taskCaseIds[i] + ': ' + error.getMessage()
                    );
                }
            }
        }
    }
}
