public class RecurringGiftService {
    public class RecurringGiftException extends Exception {}

    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;
        public Date startDate;
        public Integer installments;
        public String paymentMethod;
    }

    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        List<Id> giftIds = new List<Id>();

        if (requests == null || requests.isEmpty()) {
            return giftIds;
        }

        // Validate every request before performing DML.
        for (GiftRequest request : requests) {
            if (request == null ||
                request.contactId == null ||
                request.amount == null ||
                request.amount <= 0 ||
                request.dayOfMonth == null ||
                request.dayOfMonth < 1 ||
                request.dayOfMonth > 31 ||
                request.startDate == null) {
                throw new RecurringGiftException(
                    'Each gift requires a contact, positive amount, day of month from 1 to 31, and start date.'
                );
            }
        }

        List<npe03__Recurring_Donation__c> donations =
            new List<npe03__Recurring_Donation__c>();

        for (GiftRequest request : requests) {
            Boolean isOpenEnded =
                request.installments == null || request.installments == 0;

            npe03__Recurring_Donation__c donation =
                new npe03__Recurring_Donation__c();

            donation.npe03__Contact__c = request.contactId;
            donation.npe03__Amount__c = request.amount;
            donation.npe03__Installment_Period__c = 'Monthly';
            donation.npe03__Installments__c =
                isOpenEnded ? null : request.installments;
            donation.npe03__Date_Established__c = request.startDate;
            donation.npe03__Next_Payment_Date__c = request.startDate;

            donation.npsp__RecurringType__c =
                isOpenEnded ? 'Open' : 'Fixed';
            donation.npsp__InstallmentFrequency__c = 1;
            donation.npsp__Day_of_Month__c =
                String.valueOf(request.dayOfMonth);
            donation.npsp__Always_Use_Last_Day_Of_Month__c =
                request.dayOfMonth == 31;
            donation.npsp__StartDate__c = request.startDate;
            donation.npsp__Status__c = 'Active';
            donation.npsp__PaymentMethod__c = request.paymentMethod;

            if (!isOpenEnded) {
                donation.npsp__EndDate__c =
                    getInstallmentDate(request, request.installments - 1);
            }

            donations.add(donation);
        }

        insert donations;

        for (npe03__Recurring_Donation__c donation : donations) {
            giftIds.add(donation.Id);
        }

        return giftIds;
    }

    private static Date getInstallmentDate(
        GiftRequest request,
        Integer monthOffset
    ) {
        Date monthStart = Date.newInstance(
            request.startDate.year(),
            request.startDate.month(),
            1
        ).addMonths(monthOffset);

        Date nextMonthStart = monthStart.addMonths(1);
        Integer lastDayOfMonth = nextMonthStart.addDays(-1).day();
        Integer installmentDay =
            Math.min(request.dayOfMonth, lastDayOfMonth);

        return Date.newInstance(
            monthStart.year(),
            monthStart.month(),
            installmentDay
        );
    }
}
