public without sharing class TA_Contact_PreventDuplicateEmail
    implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    private static final String DUPLICATE_EMAIL_ERROR =
        'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        List<Contact> contacts = (List<Contact>) triggerNew;
        validateCandidates(contacts, new Set<Id>());
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Contact> newContacts = (List<Contact>) triggerNew;
        List<Contact> oldContacts = (List<Contact>) triggerOld;

        List<Contact> candidates = new List<Contact>();
        Set<Id> candidateIds = new Set<Id>();

        for (Integer i = 0; i < newContacts.size(); i++) {
            Contact newContact = newContacts[i];
            Contact oldContact = oldContacts[i];

            Boolean emailChanged =
                newContact.Email == null
                    ? oldContact.Email != null
                    : oldContact.Email == null || !newContact.Email.equals(oldContact.Email);

            if ((emailChanged || newContact.AccountId != oldContact.AccountId) &&
                newContact.AccountId != null &&
                newContact.Email != null) {
                candidates.add(newContact);
                candidateIds.add(newContact.Id);
            }
        }

        validateCandidates(candidates, candidateIds);
    }

    private static void validateCandidates(
        List<Contact> candidates,
        Set<Id> candidateIds
    ) {
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();

        for (Contact candidate : candidates) {
            if (candidate.AccountId != null && candidate.Email != null) {
                accountIds.add(candidate.AccountId);
                emails.add(candidate.Email);
            }
        }

        if (accountIds.isEmpty() || emails.isEmpty()) {
            return;
        }

        Set<String> existingKeys = new Set<String>();
        List<Contact> existingContacts;

        if (candidateIds.isEmpty()) {
            existingContacts = [
                SELECT AccountId, Email
                FROM Contact
                WHERE AccountId IN :accountIds
                    AND Email IN :emails
            ];
        } else {
            existingContacts = [
                SELECT AccountId, Email
                FROM Contact
                WHERE AccountId IN :accountIds
                    AND Email IN :emails
                    AND Id NOT IN :candidateIds
            ];
        }

        for (Contact existingContact : existingContacts) {
            existingKeys.add(makeKey(existingContact.AccountId, existingContact.Email));
        }

        Set<String> acceptedKeys = new Set<String>();

        // Preserve trigger-list order: the first candidate for a key is accepted.
        for (Contact candidate : candidates) {
            if (candidate.AccountId == null || candidate.Email == null) {
                continue;
            }

            String key = makeKey(candidate.AccountId, candidate.Email);
            if (existingKeys.contains(key) || acceptedKeys.contains(key)) {
                candidate.addError(DUPLICATE_EMAIL_ERROR);
            } else {
                acceptedKeys.add(key);
            }
        }
    }

    private static String makeKey(Id accountId, String email) {
        return String.valueOf(accountId) + '|' + email.toLowerCase();
    }
}
